PREFIX sft: <http://www.semanticweb.org/KG-SFT#>
SELECT
  (REPLACE(STR(?sport_facility), "http://localhost:8080/source/SportFacility/","") AS ?id)
  ?time
WHERE {
   ?route a sft:route ;
        sft:has_time ?time .
   ?sport_facility a sft:sport_facility ;
        sft:has_meanOfTransport ?mean_of_transport .
   {
     SELECT ?mean_of_transport (MIN(?route) AS ?route)
     WHERE {
        ?route a sft:route ;
             sft:has_meanOfTransport ?mean_of_transport .
     }
     GROUP BY ?mean_of_transport
   }
}

